// Static fixed buffer for speed
#define MAX_ITEMS 100
Item fixed_buffer[MAX_ITEMS];
size_t buffer_count = 0;

// Dynamic allocation for large items
typedef struct {
    size_t size;
    void* data;
} LargeItem;

LargeItem* create_large(size_t s) {
    LargeItem* li = malloc(sizeof(LargeItem));
    li->size = s;
    li->data = malloc(s);
    return li;
}

void destroy_large(LargeItem* li) {
    free(li->data);
    free(li);
}
